def _maybe_quant_load(model_id: str):
    """CHAMBER_QUANT=1: load large MoE checkpoints 4-bit (NF4, double quant, bf16 compute) per the hub
    config's own quantization_config, with offload tiers on GPU/RAM. Unchanged behaviour otherwise."""
    import os
    if os.environ.get("CHAMBER_QUANT") != "1":
        return AutoModelForCausalLM.from_pretrained(MODEL_ID, torch_dtype=DTYPE, device_map=DEVICE)
    from transformers import BitsAndBytesConfig
    cfg = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4", bnb_4bit_compute_dtype=torch.bfloat16,
                             bnb_4bit_use_double_quant=True)
    return AutoModelForCausalLM.from_pretrained(
        MODEL_ID, torch_dtype=DTYPE, quantization_config=cfg,
        device_map="auto", max_memory={0: "22GiB", "cpu": "40GiB"},
        offload_folder=os.environ.get("CHAMBER_OFFLOAD", "/workspace/offload"), low_cpu_mem_usage=True)


